const trajectory = data && data.trajectory;
const samples = trajectory && Array.isArray(trajectory.samples) ? trajectory.samples : [];
const geometry = trajectory && trajectory.geometry ? trajectory.geometry : {};
const panels = geometry && Array.isArray(geometry.panels) ? geometry.panels : [];
const foldPlan = data && data.fold_plan ? data.fold_plan : null;

root.style.width = "100%";
root.style.height = "100%";
root.style.minHeight = "280px";
root.style.position = "relative";
root.style.overflow = "hidden";
root.style.background = "#ffffff";

if (samples.length < 2) {
  const empty = document.createElement("div");
  empty.textContent = "No visualization data yet.";
  empty.style.cssText = "height:280px;display:grid;place-items:center;color:#86868b;font:13px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif";
  root.appendChild(empty);
} else {
  const flightCanvas = document.createElement("canvas");
  flightCanvas.style.cssText = "position:absolute;inset:0;display:block;width:100%;height:100%;min-height:280px";
  root.appendChild(flightCanvas);

  const geometryCanvas = document.createElement("canvas");
  geometryCanvas.style.cssText = "position:absolute;inset:0;display:block;width:100%;height:100%;min-height:280px;opacity:0";
  root.appendChild(geometryCanvas);

  const overlayCanvas = document.createElement("canvas");
  overlayCanvas.style.cssText = "position:absolute;inset:0;display:block;width:100%;height:100%;min-height:280px;opacity:0;pointer-events:none";
  root.appendChild(overlayCanvas);

  const foldCanvas = document.createElement("canvas");
  foldCanvas.style.cssText = "position:absolute;inset:0;display:block;width:100%;height:100%;min-height:280px;opacity:0;pointer-events:none";
  root.appendChild(foldCanvas);

  const note = document.createElement("span");
  note.textContent = "current best trajectory";
  note.style.cssText = "position:absolute;left:14px;bottom:10px;color:#86868b;font:11px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif";
  root.appendChild(note);

  const ctx = flightCanvas.getContext("2d");
  const overlay = overlayCanvas.getContext("2d");
  const foldCtx = foldCanvas.getContext("2d");
  const xs = samples.map(sample => sample[1]);
  const zs = samples.map(sample => sample[3]);
  const minX = Math.min(...xs, 0);
  const maxX = Math.max(...xs, 1);
  const maxZ = Math.max(...zs, 1);
  const durationMs = Math.max(1200, Number(trajectory.flight_time_s || samples[samples.length - 1][0] || 1) * 1000);
  const transitionMs = 650;
  const geometryHoldMs = 6500;
  const foldTransitionMs = 650;
  const pad = 28;
  const animationStart = performance.now();
  let geometryRenderer = null;
  let geometryRendererFailed = false;

  function resizeCanvas(canvas) {
    const rect = canvas.getBoundingClientRect();
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    const width = Math.max(1, Math.floor(rect.width * ratio));
    const height = Math.max(1, Math.floor(rect.height * ratio));
    const changed = canvas.width !== width || canvas.height !== height;
    if (changed) {
      canvas.width = width;
      canvas.height = height;
    }
    return changed;
  }

  function resizeAll() {
    return resizeCanvas(flightCanvas) | resizeCanvas(geometryCanvas) | resizeCanvas(overlayCanvas) | resizeCanvas(foldCanvas);
  }

  function trajectoryPoint(sample) {
    const scaleX = (flightCanvas.width - pad * 2) / Math.max(maxX - minX, 0.001);
    const scaleZ = (flightCanvas.height - pad * 2) / Math.max(maxZ, 0.001);
    return [
      pad + (sample[1] - minX) * scaleX,
      flightCanvas.height - pad - sample[3] * scaleZ,
    ];
  }

  function drawFlight(progress, alpha) {
    ctx.clearRect(0, 0, flightCanvas.width, flightCanvas.height);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = "#f0f0f2";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let line = 1; line < 8; ++line) {
      const y = (flightCanvas.height / 8) * line;
      ctx.moveTo(0, y);
      ctx.lineTo(flightCanvas.width, y);
    }
    ctx.stroke();

    ctx.strokeStyle = "#d2d2d7";
    ctx.beginPath();
    ctx.moveTo(0, flightCanvas.height - pad);
    ctx.lineTo(flightCanvas.width, flightCanvas.height - pad);
    ctx.stroke();

    ctx.strokeStyle = "#86868b";
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    samples.forEach((sample, index) => {
      const [x, y] = trajectoryPoint(sample);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    const sampleIndex = Math.min(samples.length - 1, Math.floor(progress * (samples.length - 1)));
    const nextIndex = Math.min(samples.length - 1, sampleIndex + 1);
    const [x, y] = trajectoryPoint(samples[sampleIndex]);
    const [nextX, nextY] = trajectoryPoint(samples[nextIndex]);
    const angle = Math.atan2(nextY - y, nextX - x);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.fillStyle = "#ffffff";
    ctx.strokeStyle = "#1d1d1f";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-7, -5);
    ctx.lineTo(-3, 0);
    ctx.lineTo(-7, 5);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  function subtract3(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
  function cross3(a, b) { return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; }
  function normalize3(v) {
    const length = Math.hypot(v[0], v[1], v[2]);
    return length < 1e-9 ? [0, 0, 1] : [v[0] / length, v[1] / length, v[2] / length];
  }
  function edgeKey(a, b) {
    const pointKey = point => point.map(value => Math.round(value * 1000000)).join(",");
    const ka = pointKey(a);
    const kb = pointKey(b);
    return ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
  }

  function createGeometryRenderer() {
    const gl = geometryCanvas.getContext("webgl", { alpha: true, antialias: true, depth: true, premultipliedAlpha: false });
    if (!gl || !panels.length) return null;

    const modelPanels = panels.map((panel, index) => {
      const corners = panel.corners.map(point => [Number(point[0]), Number(point[1]), Number(point[2])]);
      const normal = normalize3(cross3(subtract3(corners[1], corners[0]), subtract3(corners[3], corners[0])));
      return { index, vertical: !!panel.vertical, corners, normal };
    });
    const allModelPoints = modelPanels.flatMap(panel => panel.corners);
    const minMX = Math.min(...allModelPoints.map(p => p[0]));
    const maxMX = Math.max(...allModelPoints.map(p => p[0]));
    const minMY = Math.min(...allModelPoints.map(p => p[1]));
    const maxMY = Math.max(...allModelPoints.map(p => p[1]));
    const minMZ = Math.min(...allModelPoints.map(p => p[2]));
    const maxMZ = Math.max(...allModelPoints.map(p => p[2]));
    const center = [(minMX + maxMX) * 0.5, (minMY + maxMY) * 0.5, (minMZ + maxMZ) * 0.5];
    const modelSize = Math.max(maxMX - minMX, maxMY - minMY, (maxMZ - minMZ) * 1.8, 0.05);

    const edgeOwners = new Map();
    modelPanels.forEach(panel => {
      for (let edge = 0; edge < 4; ++edge) {
        const a = panel.corners[edge];
        const b = panel.corners[(edge + 1) % 4];
        const key = edgeKey(a, b);
        if (!edgeOwners.has(key)) edgeOwners.set(key, []);
        edgeOwners.get(key).push(panel);
      }
    });

    function edgeClass(panel, a, b) {
      const owners = edgeOwners.get(edgeKey(a, b)) || [];
      if (owners.length <= 1) return "silhouette";
      const other = owners.find(owner => owner.index !== panel.index);
      if (!other) return "panel";
      if (panel.vertical !== other.vertical) return "crease";
      const dot = Math.max(-1, Math.min(1, panel.normal[0] * other.normal[0] + panel.normal[1] * other.normal[1] + panel.normal[2] * other.normal[2]));
      return Math.acos(Math.abs(dot)) * 180 / Math.PI > 2.0 ? "crease" : "panel";
    }

    let currentYaw = 0;
    function rotatedPoint(p) {
      const x = p[0] - center[0];
      const y = p[1] - center[1];
      const z = p[2] - center[2];
      const c = Math.cos(currentYaw);
      const s = Math.sin(currentYaw);
      return [x * c - y * s, x * s + y * c, z];
    }

    function cameraPoint(p) {
      const r = rotatedPoint(p);
      return [
        r[0] * 0.82 - r[1] * 0.72,
        r[0] * 0.36 + r[1] * 0.40 - r[2] * 1.45,
        r[0] * 1.044 + r[1] * 1.189 + r[2] * 0.5872,
      ];
    }

    function clipPoint(modelPoint) {
      const p = cameraPoint(modelPoint);
      const scale = 1.45 / modelSize;
      return [p[0] * scale, -p[1] * scale - 0.03, Math.max(-0.95, Math.min(0.95, -p[2] * scale * 0.42))];
    }

    const vertexShaderSource = `attribute vec3 aPosition; void main(){ gl_Position = vec4(aPosition, 1.0); }`;
    const fragmentShaderSource = `precision mediump float; uniform vec4 uColor; void main(){ gl_FragColor = uColor; }`;
    function compile(type, source) {
      const shader = gl.createShader(type);
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) { gl.deleteShader(shader); return null; }
      return shader;
    }
    const vertexShader = compile(gl.VERTEX_SHADER, vertexShaderSource);
    const fragmentShader = compile(gl.FRAGMENT_SHADER, fragmentShaderSource);
    if (!vertexShader || !fragmentShader) return null;
    const program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
    const positionLocation = gl.getAttribLocation(program, "aPosition");
    const colorLocation = gl.getUniformLocation(program, "uColor");
    const buffer = gl.createBuffer();

    function drawVertices(mode, points, color) {
      const flattened = new Float32Array(points.flatMap(clipPoint));
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, flattened, gl.STREAM_DRAW);
      gl.vertexAttribPointer(positionLocation, 3, gl.FLOAT, false, 0, 0);
      gl.enableVertexAttribArray(positionLocation);
      gl.uniform4fv(colorLocation, color);
      gl.drawArrays(mode, 0, points.length);
    }

    function overlayPoint(modelPoint) {
      const clip = clipPoint(modelPoint);
      return [(clip[0] * 0.5 + 0.5) * overlayCanvas.width, (1 - (clip[1] * 0.5 + 0.5)) * overlayCanvas.height];
    }

    function drawOverlay() {
      overlay.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
      const width = geometryCanvas.width;
      const length = Number(geometry.length_m || 0.297);
      const span = Number(geometry.span_m || 0.18);
      const axisX = Math.max(length * 0.24, 0.040);
      const axisY = Math.max(span * 0.24, 0.032);
      const axisZ = Math.max(Math.min(length, span) * 0.23, 0.028);
      const origin = overlayPoint(center);

      function drawAxis(offset, label, dx, dy) {
        const to = overlayPoint([center[0] + offset[0], center[1] + offset[1], center[2] + offset[2]]);
        const vx = to[0] - origin[0];
        const vy = to[1] - origin[1];
        const length2d = Math.max(Math.hypot(vx, vy), 0.001);
        const ux = vx / length2d;
        const uy = vy / length2d;
        const arrow = Math.max(5, width / 150);
        overlay.strokeStyle = "#6e6e73";
        overlay.fillStyle = "#1d1d1f";
        overlay.lineWidth = 1.4;
        overlay.beginPath(); overlay.moveTo(origin[0], origin[1]); overlay.lineTo(to[0], to[1]); overlay.stroke();
        overlay.beginPath();
        overlay.moveTo(to[0], to[1]);
        overlay.lineTo(to[0] - ux * arrow - uy * arrow * 0.45, to[1] - uy * arrow + ux * arrow * 0.45);
        overlay.lineTo(to[0] - ux * arrow + uy * arrow * 0.45, to[1] - uy * arrow - ux * arrow * 0.45);
        overlay.closePath(); overlay.fill();
        overlay.font = `500 ${Math.max(10, width / 90)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        overlay.textAlign = "center";
        overlay.fillText(label, to[0] + dx, to[1] + dy);
      }

      drawAxis([axisX, 0, 0], "+X", 12, -5);
      drawAxis([0, axisY, 0], "+Y", -12, 8);
      drawAxis([0, 0, axisZ], "+Z  TOP", 0, -10);
      drawAxis([0, 0, -axisZ], "BOTTOM  -Z", 0, 14);
      overlay.fillStyle = "#1d1d1f";
      overlay.beginPath(); overlay.arc(origin[0], origin[1], Math.max(2, width / 350), 0, Math.PI * 2); overlay.fill();
      overlay.font = `600 ${Math.max(12, width / 64)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
      overlay.textAlign = "center";
      overlay.fillText("optimized geometry", width * 0.5, Math.max(18, width / 48));
    }

    function render(now) {
      currentYaw = 0.14 * Math.sin((now || 0) * 0.00085);
      gl.viewport(0, 0, geometryCanvas.width, geometryCanvas.height);
      gl.clearColor(1, 1, 1, 0);
      gl.clearDepth(1.0);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      gl.useProgram(program);
      gl.enable(gl.DEPTH_TEST);
      gl.depthFunc(gl.LEQUAL);
      gl.disable(gl.CULL_FACE);
      gl.enable(gl.POLYGON_OFFSET_FILL);
      gl.polygonOffset(1.0, 1.0);
      modelPanels.forEach(panel => {
        const c = panel.corners;
        drawVertices(gl.TRIANGLES, [c[0], c[1], c[2], c[0], c[2], c[3]], panel.vertical ? [0.945, 0.945, 0.955, 1] : [0.992, 0.992, 0.992, 1]);
      });
      gl.disable(gl.POLYGON_OFFSET_FILL);
      modelPanels.forEach(panel => {
        for (let edge = 0; edge < 4; ++edge) {
          const a = panel.corners[edge];
          const b = panel.corners[(edge + 1) % 4];
          const kind = edgeClass(panel, a, b);
          const color = kind === "silhouette" ? [0.11, 0.11, 0.12, 1] : kind === "crease" ? [0.37, 0.37, 0.39, 1] : [0.84, 0.84, 0.86, 1];
          drawVertices(gl.LINES, [a, b], color);
        }
      });
      drawOverlay();
    }
    return { render };
  }

  function drawGeometryFallback() {
    overlay.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
    overlay.fillStyle = "#86868b";
    overlay.font = `${Math.max(12, overlayCanvas.width / 70)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
    overlay.textAlign = "center";
    overlay.fillText("WebGL geometry renderer unavailable", overlayCanvas.width * 0.5, overlayCanvas.height * 0.5);
  }

  function drawFoldPlan() {
    foldCtx.clearRect(0, 0, foldCanvas.width, foldCanvas.height);
    const w = foldCanvas.width;
    const h = foldCanvas.height;
    const ratio = w / Math.max(h, 1);
    const sheet = foldPlan && foldPlan.sheet ? foldPlan.sheet : { width_m: 0.210, length_m: 0.297 };
    const creases = foldPlan && Array.isArray(foldPlan.creases) ? foldPlan.creases : [];
    const steps = foldPlan && Array.isArray(foldPlan.steps) ? foldPlan.steps : [];
    const wide = ratio > 1.55;
    const planLeft = w * 0.035;
    const planTop = h * 0.145;
    const planWidth = wide ? w * 0.52 : w * 0.78;
    const planHeight = h * 0.70;
    const scale = Math.min(planWidth / Number(sheet.width_m || 0.210), planHeight / Number(sheet.length_m || 0.297));
    const sheetW = Number(sheet.width_m || 0.210) * scale;
    const sheetH = Number(sheet.length_m || 0.297) * scale;
    const sx = planLeft + (planWidth - sheetW) * 0.5;
    const sy = planTop + (planHeight - sheetH) * 0.5;

    function mapPoint(p) {
      return [sx + (Number(p[0]) + Number(sheet.width_m || 0.210) * 0.5) * scale, sy + Number(p[1]) * scale];
    }

    function drawArrow(mid, vector, length) {
      const vx = Number(vector && vector[0] || 0);
      const vy = Number(vector && vector[1] || 0);
      const norm = Math.max(Math.hypot(vx, vy), 0.001);
      const ux = vx / norm;
      const uy = vy / norm;
      const start = [mid[0] - ux * length * 0.55, mid[1] - uy * length * 0.55];
      const end = [mid[0] + ux * length * 0.45, mid[1] + uy * length * 0.45];
      const head = Math.max(5, w / 190);
      foldCtx.save();
      foldCtx.strokeStyle = "#1d1d1f";
      foldCtx.fillStyle = "#1d1d1f";
      foldCtx.lineWidth = Math.max(1.2, w / 950);
      foldCtx.beginPath(); foldCtx.moveTo(start[0], start[1]); foldCtx.lineTo(end[0], end[1]); foldCtx.stroke();
      foldCtx.beginPath();
      foldCtx.moveTo(end[0], end[1]);
      foldCtx.lineTo(end[0] - ux * head - uy * head * 0.5, end[1] - uy * head + ux * head * 0.5);
      foldCtx.lineTo(end[0] - ux * head + uy * head * 0.5, end[1] - uy * head - ux * head * 0.5);
      foldCtx.closePath(); foldCtx.fill();
      foldCtx.restore();
    }

    function wrapText(text, x, y, maxWidth, lineHeight, maxLines) {
      const words = String(text || "").split(/\s+/).filter(Boolean);
      const lines = [];
      let current = "";
      for (const word of words) {
        const trial = current ? current + " " + word : word;
        if (current && foldCtx.measureText(trial).width > maxWidth) {
          lines.push(current);
          current = word;
          if (lines.length >= maxLines - 1) break;
        } else {
          current = trial;
        }
      }
      if (current && lines.length < maxLines) lines.push(current);
      lines.slice(0, maxLines).forEach((line, index) => foldCtx.fillText(line, x, y + index * lineHeight));
      return lines.length;
    }

    foldCtx.fillStyle = "#ffffff";
    foldCtx.fillRect(sx, sy, sheetW, sheetH);
    foldCtx.strokeStyle = "#1d1d1f";
    foldCtx.lineWidth = Math.max(1.5, w / 800);
    foldCtx.strokeRect(sx, sy, sheetW, sheetH);

    foldCtx.font = `500 ${Math.max(10, w / 100)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
    foldCtx.fillStyle = "#86868b";
    foldCtx.textAlign = "center";
    foldCtx.fillText("NOSE", sx + sheetW * 0.5, sy - Math.max(8, h * 0.018));
    foldCtx.fillText("TAIL", sx + sheetW * 0.5, sy + sheetH + Math.max(14, h * 0.035));

    const drawnStep = new Set();
    creases.forEach(crease => {
      const a = mapPoint(crease.a);
      const b = mapPoint(crease.b);
      const kind = crease.kind || "fold";
      const foldType = crease.fold_type || "valley";
      foldCtx.save();
      foldCtx.strokeStyle = foldType === "reference" ? "#3a3a3c" : foldType === "mountain" ? "#4c4c50" : foldType === "adjust" ? "#9a9aa0" : "#66666b";
      foldCtx.lineWidth = foldType === "reference" || kind === "wing" ? Math.max(1.5, w / 850) : Math.max(1, w / 1050);
      if (foldType === "reference") foldCtx.setLineDash([Math.max(6, w / 170), Math.max(5, w / 210)]);
      if (foldType === "mountain") foldCtx.setLineDash([Math.max(10, w / 130), Math.max(3, w / 320), Math.max(3, w / 320), Math.max(3, w / 320)]);
      if (foldType === "adjust") foldCtx.setLineDash([Math.max(4, w / 230), Math.max(4, w / 230)]);
      foldCtx.beginPath(); foldCtx.moveTo(a[0], a[1]); foldCtx.lineTo(b[0], b[1]); foldCtx.stroke();
      foldCtx.restore();

      const mx = (a[0] + b[0]) * 0.5;
      const my = (a[1] + b[1]) * 0.5;
      drawArrow([mx, my], crease.arrow || [0, 0], Math.max(18, Math.min(sheetW, sheetH) * 0.075));

      const step = Number(crease.step || 0);
      if (step && !drawnStep.has(step)) {
        drawnStep.add(step);
        const r = Math.max(8, w / 105);
        foldCtx.fillStyle = "#ffffff";
        foldCtx.strokeStyle = "#1d1d1f";
        foldCtx.lineWidth = 1.2;
        foldCtx.beginPath(); foldCtx.arc(mx, my, r, 0, Math.PI * 2); foldCtx.fill(); foldCtx.stroke();
        foldCtx.fillStyle = "#1d1d1f";
        foldCtx.font = `600 ${Math.max(10, w / 108)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        foldCtx.textAlign = "center";
        foldCtx.textBaseline = "middle";
        foldCtx.fillText(String(step), mx, my + 0.5);
        foldCtx.textBaseline = "alphabetic";
      }
    });

    foldCtx.fillStyle = "#1d1d1f";
    foldCtx.font = `600 ${Math.max(13, w / 66)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
    foldCtx.textAlign = "center";
    foldCtx.fillText("winning A4 fold plan", w * 0.5, Math.max(20, w / 48));

    if (wide && steps.length) {
      const tx = w * 0.60;
      const ty = h * 0.175;
      const right = w * 0.965;
      const textWidth = Math.max(120, right - tx - Math.max(28, w / 28));
      const blockHeight = Math.max(46, h * 0.112);
      foldCtx.textAlign = "left";
      steps.slice(0, 6).forEach((step, index) => {
        const y = ty + index * blockHeight;
        const r = Math.max(8, w / 108);
        const creaseForStep = creases.find(crease => Number(crease.step) === Number(step.step));
        const type = creaseForStep && creaseForStep.fold_type ? String(creaseForStep.fold_type).toUpperCase() : "FOLD";

        foldCtx.fillStyle = "#1d1d1f";
        foldCtx.beginPath(); foldCtx.arc(tx, y, r, 0, Math.PI * 2); foldCtx.fill();
        foldCtx.fillStyle = "#ffffff";
        foldCtx.font = `600 ${Math.max(9, w / 118)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        foldCtx.textAlign = "center";
        foldCtx.textBaseline = "middle";
        foldCtx.fillText(String(step.step), tx, y + 0.5);
        foldCtx.textBaseline = "alphabetic";

        const textX = tx + r + Math.max(9, w / 115);
        foldCtx.fillStyle = "#1d1d1f";
        foldCtx.textAlign = "left";
        foldCtx.font = `600 ${Math.max(10, w / 100)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        foldCtx.fillText(step.title, textX, y - Math.max(5, h * 0.010));
        foldCtx.fillStyle = "#86868b";
        foldCtx.font = `500 ${Math.max(8, w / 132)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        const badgeWidth = foldCtx.measureText(type).width + Math.max(12, w / 100);
        foldCtx.strokeStyle = "#d2d2d7";
        foldCtx.strokeRect(right - badgeWidth, y - Math.max(17, h * 0.035), badgeWidth, Math.max(15, h * 0.032));
        foldCtx.fillText(type, right - badgeWidth + Math.max(6, w / 200), y - Math.max(6, h * 0.012));

        foldCtx.fillStyle = "#6e6e73";
        foldCtx.font = `400 ${Math.max(9, w / 124)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
        wrapText(step.instruction, textX, y + Math.max(12, h * 0.025), textWidth, Math.max(12, h * 0.027), 2);
      });
    }

    const legendY = h - Math.max(30, h * 0.067);
    foldCtx.textAlign = "center";
    foldCtx.fillStyle = "#6e6e73";
    foldCtx.font = `500 ${Math.max(8, w / 135)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
    foldCtx.fillText("arrows show the moving flap · dashed = reference · dash-dot = wing fold · short dash = angle adjustment", w * 0.5, legendY);
    foldCtx.fillStyle = "#86868b";
    foldCtx.font = `400 ${Math.max(8, w / 140)}px -apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif`;
    foldCtx.fillText("simplified reproducible guide · one uncut A4 sheet · not a rigid-origami layer solver", w * 0.5, h - Math.max(11, h * 0.027));
  }

  function setOpacity(flight, model, overlayValue, fold) {
    flightCanvas.style.opacity = String(flight);
    geometryCanvas.style.opacity = String(model);
    overlayCanvas.style.opacity = String(overlayValue);
    foldCanvas.style.opacity = String(fold);
  }

  function draw(now) {
    const resized = resizeAll();
    if (!geometryRenderer && !geometryRendererFailed && panels.length) {
      geometryRenderer = createGeometryRenderer();
      if (!geometryRenderer) { geometryRendererFailed = true; drawGeometryFallback(); }
    }
    if (resized) drawFoldPlan();

    const elapsed = now - animationStart;
    const flightEnd = durationMs;
    const geometryStart = flightEnd + transitionMs;
    const geometryEnd = geometryStart + geometryHoldMs;
    const foldStart = geometryEnd + foldTransitionMs;

    if (elapsed < flightEnd) {
      note.textContent = "current best trajectory";
      setOpacity(1, 0, 0, 0);
      drawFlight(Math.max(0, Math.min(1, elapsed / durationMs)), 1);
      requestAnimationFrame(draw);
      return;
    }

    if (elapsed < geometryStart) {
      const blend = (elapsed - flightEnd) / transitionMs;
      note.textContent = blend < 0.5 ? "current best trajectory" : "winning geometry";
      setOpacity(1 - blend, blend, blend, 0);
      drawFlight(1, 1);
      if (geometryRenderer) geometryRenderer.render(now);
      requestAnimationFrame(draw);
      return;
    }

    if (elapsed < geometryEnd) {
      note.textContent = "winning geometry";
      setOpacity(0, 1, 1, 0);
      if (geometryRenderer) geometryRenderer.render(now);
      requestAnimationFrame(draw);
      return;
    }

    if (elapsed < foldStart) {
      const blend = (elapsed - geometryEnd) / foldTransitionMs;
      note.textContent = blend < 0.5 ? "winning geometry" : "winning fold plan";
      setOpacity(0, 1 - blend, 1 - blend, blend);
      if (geometryRenderer) geometryRenderer.render(now);
      drawFoldPlan();
      requestAnimationFrame(draw);
      return;
    }

    note.textContent = "winning fold plan";
    setOpacity(0, 0, 0, 1);
    drawFoldPlan();
  }

  drawFoldPlan();
  requestAnimationFrame(draw);
}
